/**
 * District boundary configuration. The boundary file is supplied by the team and
 * is never downloaded or generated by the app (see scripts/simplify-boundaries.md).
 */

/** Tried in order; the first file that exists is used. */
export const BOUNDARY_URLS = ['/geo/india_districts.topojson', '/geo/india_districts.geojson'] as const

/** Optional crosswalk that supplies LGD codes (and Census 2011 codes for joining). */
export const LGD_CSV_URL = '/data/lgd_districts.csv'

/**
 * Accepted property names per field, first match wins. Covers our normalised
 * schema and DataMeet's Census 2011 district layer.
 */
export const BOUNDARY_PROPERTY_ALIASES = {
  lgd_code: ['lgd_code', 'LGD_CODE', 'lgd_district_code'],
  district: ['district', 'DISTRICT', 'dtname', 'NAME_2'],
  state: ['state', 'ST_NM', 'STATE', 'stname'],
  census2011_code: ['census2011_code', 'censuscode', 'DT_CEN_CD', 'dt_code'],
} as const

/** Shown under every geographic map when the boundary file is loaded. */
export const BOUNDARY_ATTRIBUTION = {
  holder: 'DataMeet',
  url: 'https://github.com/datameet/maps/tree/master/Districts/Census_2011',
  license: 'CC BY 2.5 IN',
  licenseUrl: 'https://creativecommons.org/licenses/by/2.5/in/',
  /** Plain-text form: "District boundaries © DataMeet (CC BY 2.5 IN) · indicative, not official". */
  text: 'District boundaries © DataMeet (CC BY 2.5 IN) · indicative, not official',
} as const

/**
 * Why a demo district has no shape in the boundary file. Shown in the table and
 * district panel. The district is never drawn inside its parent's shape.
 */
export const NO_BOUNDARY_NOTES: Record<string, string> = {
  'medchal malkajgiri': 'No 2011 boundary (district created 2016)',
}

export const NO_BOUNDARY_DEFAULT_NOTE = 'No matching shape in the boundary file'

/**
 * Name-matching fallback, used ONLY when LGD codes are not available on both
 * sides. Keys are current names (lower-case); values are older spellings found
 * in Census 2011 boundary layers such as DataMeet's. The UI labels a name join.
 */
export const STATE_NAME_ALIASES: Record<string, string[]> = {
  delhi: ['nct of delhi'],
  // Census 2011 layers predate Telangana (2014).
  telangana: ['andhra pradesh'],
}

